INSERT INTO `creature_template_scaling` (`Entry`, `LevelScalingMin`, `LevelScalingMax`, `LevelScalingDeltaMin`, `LevelScalingDeltaMax`, `LevelScalingDuration`, `VerifiedBuild`) VALUES (23543, 11, 110, 0, 0, 0, 25996);
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextID`, `MinTimer`, `MaxTimer`, `SpellID`, `comment`) VALUES
(23543, 0, 0, 'Prepare yourselves, the bells have tolled! Shelter your weak, your young and your old! Each of you shall pay the final sum! Cry for mercy; the reckoning has come!', 14, 0, 100, 0, 0, 0, 22022, 0, 0, 0, 'Shade of the Horseman - Prepare'),
(23543, 1, 0, 'The sky is dark.  The fire burns.  You strive in vain as Fate''s wheel turns.', 14, 0, 100, 0, 0, 0, 22034, 0, 0, 0, 'Shade of the Horseman - Midway'),
(23543, 2, 0, 'The town still burns, a cleansing fire!  Time is short, I''ll soon retire!', 14, 0, 100, 0, 0, 0, 22035, 0, 0, 0, 'Shade of the Horseman - Time short'),
(23543, 3, 0, 'Fire consumes! You''ve tried and failed.  Let there be no doubt, justice prevailed!', 14, 0, 100, 0, 0, 0, 22026, 0, 0, 0, 'Shade of the Horseman - Failed'),
(23543, 4, 0, 'My flames have died, left not a spark. I shall send you myself, to the lifeless dark.', 14, 0, 100, 0, 0, 0, 22027, 0, 0, 0, 'Shade of the Horseman - Fires out'),
(23543, 5, 0, 'Harken, cur!  Tis you I spurn!  Now feel... the burn!', 14, 0, 100, 0, 0, 0, 22587, 0, 0, 0, 'Shade of the Horseman - Conflagration'),
(23543, 6, 0, 'So eager you are, for my blood to spill. Yet to vanquish me, ''tis my head you must kill!', 14, 0, 100, 0, 0, 0, 22757, 0, 0, 0, 'Shade of the Horseman - Death');
