-- Hallow's End: the Shade of the Horseman attacks the starting villages, fires and water buckets scripted

-- Scripts replace the old SmartAI
UPDATE `creature_template` SET `AIName` = '', `ScriptName` = 'npc_hallows_end_fire' WHERE `entry` = 23537;
UPDATE `creature_template` SET `AIName` = '', `ScriptName` = 'npc_shade_of_the_horseman' WHERE `entry` = 23543;
UPDATE `creature_template` SET `ScriptName` = 'npc_hallows_end_orphan_matron' WHERE `entry` IN (24519, 23973);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (23537, 23543);

-- The Shade is summoned by "Let the Fires Come!", he no longer stands in Goldshire and Razor Hill all holiday long
DELETE FROM `game_event_creature` WHERE `guid` IN (167197, 167198);
DELETE FROM `creature_addon` WHERE `guid` IN (167197, 167198);
DELETE FROM `creature` WHERE `guid` IN (167197, 167198);

DELETE FROM `creature_template_scaling` WHERE `Entry` = 23543;

DELETE FROM `creature_text` WHERE `CreatureID` = 23543;

-- Bucket Lands only reaches fires and players
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 13 AND `SourceEntry` = 42339;

-- The village Fires quests need Fire Brigade Practice / Fire Training
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 19 AND `SourceEntry` IN (11131, 12135, 11219, 12139);

-- Fire nodes as sniffed: 36 on the burning buildings and 5 practice fires per village
DELETE FROM `game_event_creature` WHERE `guid` IN (SELECT `guid` FROM `creature` WHERE `id` = 23537);
DELETE FROM `creature_addon` WHERE `guid` IN (SELECT `guid` FROM `creature` WHERE `id` = 23537);
DELETE FROM `creature` WHERE `id` = 23537;
DELETE FROM `game_event_creature` WHERE `guid` BETWEEN 10550001 AND 10550246;
DELETE FROM `creature` WHERE `guid` BETWEEN 10550001 AND 10550246;

-- Water barrels as sniffed: one by the matron, one by the practice fires
DELETE FROM `game_event_gameobject` WHERE `guid` IN (SELECT `guid` FROM `gameobject` WHERE `id` = 186234);
DELETE FROM `gameobject` WHERE `id` = 186234;
DELETE FROM `game_event_gameobject` WHERE `guid` BETWEEN 25820001 AND 25820012;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 25820001 AND 25820012;
